/* 叙事索引: 每条卷剧情分得全局数字编号 sid(按代码顺序稳定)。
 * 修行录存档只存 sid 数字引用(瘦存档), 渲染/回看时从静态表还原剧情 */
const STORY_BY_SID = {};
const STORY_BY_KEY = {};
(function () {
  let sid = 0;
  for (const vol of PLOT) for (const b of vol) {
    b.sid = ++sid;
    STORY_BY_SID[sid] = b;
    STORY_BY_KEY[b.key] = b;
  }
})();
function storyResolve(j) {          // journal 条目 → 剧情内容(数字引用还原 / 旧档直读)
  if (j && j.sid && STORY_BY_SID[j.sid]) return STORY_BY_SID[j.sid];
  return j;
}
function journalHasKey(b) {         // 兼容新旧两种记录格式
  return state.journal.some(j => (j.sid && j.sid === b.sid) || (j.key && j.key === b.key));
}
function addJournal(entry) {
  const b = entry.key && STORY_BY_KEY[entry.key];
  if (b) {                          // 预置剧情: 只存数字引用, 不存文本
    state.journal.push({ sid: b.sid, big: b.big || entry.big, kind: b.kind || entry.kind, ts: Date.now() });
  } else {                          // 动态事件(离线游历/纪事等): 仍存文本
    entry.ts = Date.now();
    state.journal.push(entry);
  }
  if (state.journal.length > JRN_CAP) trimJournal();   // v1.9.2: 分流裁剪, 不再 shift 挤掉主线
  save();
}
/* 剧情推进器: 触发当前大境卷内所有"已达小层且未经历"的节点 */
function realmPlot() {
  const bi = bigIdx();
  const vol = PLOT[bi];
  if (!vol || !vol.length) return;
  const start = BIGS.slice(0, bi).reduce((s, x) => s + x.segs, 0);   // 该大境起始全局小段 idx
  const segCount = BIGS[bi].segs;
  const r = realm();
  const pos = Math.min(segCount, (state.realmIdx - start) + Math.min(1, state.exp / r.need));
  let fired = 0, last = null;
  for (let i = 0; i < vol.length; i++) {
    const b = vol[i];
    if (journalHasKey(b)) continue;
    if (pos >= segCount * i / vol.length) {
      addJournal({ key: b.key, big: b.big || realm().big, kind: b.kind || "际遇", title: b.title, text: b.text });
      fired++;
      if (fired === 1) {
        last = b;
        pushMsg("main", `<span class="b">${b.big || realm().big} · ${b.title}</span>｜${b.text}`);
      }
    }
  }
  if (fired > 1) pushMsg("main", `<span class="b">仙途拾遗</span>｜修行之间你又经历了 ${fired} 段际遇，均已记入修行录。`);
  if (fired > 0) cloudFlush();   // v1.5.1: 主线剧情入修行录 → 关键节点立即上云
  void last;
}

/* ---- 纪事里程碑: 灵石/聚灵阵/法宝的玩法节点 → 一次性叙事(不占境界剧情位) ---- */
const MS_SPIRIT = [
  [500, "灵石初丰", "你攒下第一笔像样的灵石——修行问道，总算不必为几枚碎灵石头疼。"],
  [2000, "小有身家", "灵石渐丰，你在坊市说话都硬气了几分。"],
  [10000, "万灵石", "万灵石入袋，你已称得上「有身家」的修士。"],
  [50000, "灵脉傍身", "五万灵石——当年在山村，这是你想都不敢想的数目。"],
  [200000, "视灵石如无物", "灵石渐成数字，你修的是长生，不是阿堵物。"],
];
const MS_ARRAY = [
  [3, "聚灵初成", "聚灵阵三转，灵气吞吐已胜过常人苦修。"],
  [6, "阵基叠塔", "六层阵基如叠塔，洞府灵气凝出肉眼可见的薄雾。"],
  [10, "小周天成", "阵成小周天，夜深时阵中灵光自鸣，如钟磬相和。"],
  [15, "自成洞天", "大阵自成一方小洞天，你端坐其中，修为如水入海。"],
  [20, "地脉来朝", "阵道登堂入室，方圆十里灵脉都隐隐向你汇聚。"],
  [25, "地肺吐纳", "此阵已可自行吐纳地肺之火，灵气取之不竭。"],
  [30, "阵道圆满", "阵成圆满，灵光冲霄——这已是聚灵阵道的极限。"],
];
const MS_ART = [
  ["法器之始", "你得了第一件趁手法器，神识附着其上，如臂使指。"],
  ["灵器入手", "灵器入体，宝光隐现——往后斗法，总算有了依仗。"],
  ["古宝临身", "古宝到手，道纹流转，你隐约摸到一丝岁月的痕迹。"],
  ["灵宝认主", "灵宝认主，灵性自鸣，连洞府外的灵兽都朝此低伏。"],
  ["玄天之宝", "玄天之宝现世，真元都为之战栗——此物一出，足以动一方风云。"],
];
function fireMilestone(flagKey, title, text) {
  const M = state.milestones || (state.milestones = {});
  if (M[flagKey]) return false;
  M[flagKey] = 1;
  addJournal({ key: "ms-" + flagKey, big: realm().big, kind: "纪事", title, text });
  pushMsg("main", `<span class="b">纪事</span>·${title}｜${text}`);
  return true;
}
function checkMilestones() {
  if (state.spirit > state.peakSpirit) state.peakSpirit = state.spirit;
  const q = state.arts.reduce((m, a) => Math.max(m, a.q), -1);
  if (q > state.bestArtQ) state.bestArtQ = q;
  let fired = false;
  for (const [th, t, x] of MS_SPIRIT) if (state.peakSpirit >= th && fireMilestone("s" + th, t, x)) fired = true;
  for (const [L, t, x] of MS_ARRAY) if (state.arrayLv >= L && fireMilestone("r" + L, t, x)) fired = true;
  for (let g = 1; g <= 5; g++) { const [t, x] = MS_ART[g - 1]; if (state.bestArtQ >= g && fireMilestone("a" + g, t, x)) fired = true; }
  if (fired) save();
}

function openStory() {
  const m = $("storyModal");
  if (!m) return;
  renderStory();
  m.classList.add("show");
}
function closeStory() {
  const m = $("storyModal");
  if (m) m.classList.remove("show");
}
/* 修行录渲染: 分章(chips) + 章内滚动分批, 避免一次注入大量 DOM 卡顿 */
const STORY_PAGE = 12;
let _storyChap = "";
function storyItemHtml(j) {
  const pad = n => String(n).padStart(2, "0");
  const rec = storyResolve(j);                       // sid → 静态剧情; 老档/动态事件直接读自身
  const tm = new Date(j.ts);
  const big = j.big || rec.big || "";
  const kind = j.kind || rec.kind || "际遇";
  return `<div class="j-card k-${esc(kind)}">` +
    `<div class="j-head"><span class="j-big">${esc(big)}</span>` +
    `<span class="j-kind k-${esc(kind)}">${esc(kind)}</span>` +
    `<span class="j-time">${pad(tm.getMonth() + 1)}-${pad(tm.getDate())} ${pad(tm.getHours())}:${pad(tm.getMinutes())}</span></div>` +
    `<h5>${esc(rec.title || j.title || "仙途拾遗")}</h5><p>${esc(rec.text || j.text || "")}</p></div>`;
}
function storyLoadMore(reset) {
  const body = $("storyBody");
  if (!body) return;
  const big = body.dataset.big || _storyChap;
  if (!big) return;
  const list = state.journal.filter(j => j.big === big).reverse(); // 最新在前
  let page = parseInt(body.dataset.page || "0", 10);
  if (reset) { page = 0; body.innerHTML = ""; }
  const slice = list.slice(page * STORY_PAGE, (page + 1) * STORY_PAGE);
  if (reset || slice.length) { page++; body.dataset.page = String(page); }
  if (slice.length) body.insertAdjacentHTML("beforeend", slice.map(storyItemHtml).join(""));
  if (reset) body.scrollTop = 0;
  if (reset && !slice.length) {
    body.innerHTML = `<div class="empty-hint">${big}期的际遇尚未写就。<br>先修行，路会自己走出来。</div>`;
  }
}
function showChapter(bigName) {
  const chips = $("storyChips");
  const body = $("storyBody");
  if (!body) return;
  _storyChap = bigName;
  body.dataset.big = bigName;
  body.onscroll = () => {
    if (body.scrollTop + body.clientHeight >= body.scrollHeight - 60) storyLoadMore(false);
  };
  if (chips) chips.querySelectorAll(".chip").forEach(x => x.classList.toggle("on", x.textContent === bigName));
  storyLoadMore(true);
}
function renderStory() {
  const body = $("storyBody");
  const chips = $("storyChips");
  if (!body || !chips) return;
  const bi = Math.min(bigIdx(), PLOT.length - 1);
  const walked = PLOT.slice(0, bi + 1).map(x => x[0].big).join(" → ");
  let sum = $("storySum");
  if (!sum) {
    sum = document.createElement("div");
    sum.className = "story-sum"; sum.id = "storySum";
    chips.parentNode.insertBefore(sum, chips);
  }
  sum.innerHTML = `已历仙途：<b>${walked}</b>` +
    (state.realmIdx >= TOTAL_SEGS - 1 ? "（仙途漫漫 · 已臻极巅）" : "");
  // 只显示有记载的大境章
  const order = PLOT.slice(0, bi + 1).map(v => v[0].big);
  const chapters = order.filter(b => state.journal.some(j => j.big === b));
  chips.innerHTML = "";
  if (!chapters.length) {
    body.innerHTML = `<div class="empty-hint">尚无记载。<br>仙途伊始，一切从你打坐感应灵气开始。</div>`;
    return;
  }
  chapters.forEach(name => {
    const c = document.createElement("div");
    c.className = "chip";
    c.textContent = name;
    c.onclick = () => showChapter(name);
    chips.appendChild(c);
  });
  // 默认打开当前大境章, 否则最后一章
  const last = state.journal[state.journal.length - 1];
  showChapter(chapters.includes(realm().big) ? realm().big : (last && last.big) || chapters[0]);
}

/* 历险(分身·左栏) */
const _lastPick = {};
function pickNoRepeat(arr, key) {
  const banned = _lastPick[key] || (_lastPick[key] = []);
  const cand = [];
  for (let i = 0; i < arr.length; i++) if (!banned.includes(i)) cand.push(i);
  const pool = cand.length ? cand : arr.map((_, i) => i);
  const idx = pool[(Math.random() * pool.length) | 0];
  banned.push(idx); if (banned.length > 5) banned.shift();
  return arr[idx];
}
function adventure() {
  const roll = Math.random();
  const bi = Math.min(bigIdx(), EVENTS.length - 1);
  const petTag = `<span class="pet">阿青</span>`;
  const artChance = 0.05 + bi * 0.005;
  if (roll < artChance) {
    const a = makeArt();
    const r = QUALITY[a.q];
    pushMsg("avatar", `${petTag}${pickNoRepeat(PET_FORGE, "petF")}，一件<span class="r">${a.name}</span>(<span class="${r.cls}">${r.name}</span>)出炉`);
    smartEquip(a);
  } else if (roll < 0.30) {
    const g = Math.round(8 + Math.random() * 30 + bigIdx() * 10);
    state.spirit += g;
    pushMsg("avatar", `${petTag}${pickNoRepeat(PET_COIN, "petC")}　灵石+${fmt(g)}`);
  } else if (roll < 0.62) {
    const g = Math.round(14 + Math.random() * 50 + bigIdx() * 16);
    state.spirit += g;
    pushMsg("avatar", `${petTag}${pickNoRepeat(PET_BONUS, "petB")}　气机渐盛`);
  } else if (roll < 0.84) {
    const bonus = rateNow() * (4 + Math.random() * 8);
    state.exp += bonus;
    pushMsg("avatar", `${petTag}${pickNoRepeat(PET_BONUS, "petB")}　修为+${fmt(bonus)}`);
  } else {
    state.exp += rateNow() * 1.5;
    pushMsg("avatar", `${petTag}${pickNoRepeat(PET_STILL, "petS")}`);
  }
  state.spirit += spiritRate();
  updateHUD();
}

function updateArts(highlight) {
  const row = $("artRow");
  const last6 = state.arts.slice(-6);
  row.innerHTML = last6.map((a, i) => {
    const isNew = !!(highlight && i === last6.length - 1);
    return `<span class="art${isNew ? " new" : ""}"><span class="q ${QUALITY[a.q].cls}">${QUALITY[a.q].name}</span>${a.name}</span>`;
  }).join("");
  while (state.arts.length > 4) {
    const old = state.arts.shift();
    state.spirit += Math.round(60 * Math.pow(1.6, old.q));
  }
}

/* ============ 突破粒子 ============ */
const bcv = $("burst"), bctx = bcv.getContext("2d");
let parts = [];
function sizeBurst() { bcv.width = innerWidth; bcv.height = innerHeight; }
sizeBurst(); addEventListener("resize", sizeBurst);
function burstBoom() {
  const cx = innerWidth / 2, cy = innerHeight * 0.46;
  for (let i = 0; i < 120; i++) {
    const a = Math.random() * Math.PI * 2, sp = 2 + Math.random() * 8;
    parts.push({ x: cx, y: cy, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp - 2.4,
      life: 1, size: 1.5 + Math.random() * 2.8, color: Math.random() < .75 ? "232,197,107" : "255,240,200" });
  }
}
function tickBurst(dt) {
  parts = parts.filter(p => p.life > 0);
  if (!parts.length) { bctx.clearRect(0, 0, bcv.width, bcv.height); return; }
  bctx.clearRect(0, 0, bcv.width, bcv.height);
  bctx.globalCompositeOperation = "lighter";
  for (const p of parts) {
    p.x += p.vx; p.y += p.vy; p.vy += .09; p.life -= dt * 1.2;
    bctx.fillStyle = `rgba(${p.color},${Math.max(0, p.life)})`;
    bctx.beginPath(); bctx.arc(p.x, p.y, Math.max(0, p.size * p.life), 0, 7); bctx.fill();
  }
  bctx.globalCompositeOperation = "source-over";
}

/* ============ 离线收益 ============ */
/* ============ v1.3.0 离线巡猎(本地兜底, 与后端 huntSettle 同式) ============
 * 云端不可用时照样有巡猎收益: dt ÷ ENC_PERIOD 波, 八成斗法/两成秘境,
 * 每战修为 = 挂机速率 × FIGHT_EXP_W × 0.6(挂机离线折扣), 灵石 = 灵石速率 × FIGHT_SP_W × 0.7;
 * 每战必掉一件 → 阿青静默择优: 能顶替就换上(旧件熔灵石), 不入眼当场熔炼。 */
function keepArtQuiet(a) {          // 静默版 smartEquip: 批量结算不发消息、不存档(同槽综合分择优, 同品质可替换)
  if (!state.arts || !Array.isArray(state.arts)) state.arts = [];
  const arts = state.arts;
  const idx = (typeof a.slot === "number" && a.slot < 4) ? a.slot : arts.length;
  if (idx >= arts.length) { arts.push(a); return true; }
  const w = arts[idx];
  if (!w) { arts[idx] = a; return true; }
  if (artScore(a) > artScore(w)) {
    state.spirit += Math.round(50 * Math.pow(1.6, w.q));    // 旧件熔回
    arts[idx] = a; return true;
  }
  state.spirit += Math.round(40 * Math.pow(1.5, a.q));      // 新件不入眼, 当场熔作灵石
  return false;
}
/* 离线巡猎胜负判定: 与在线 fireFight 同式的随机单场战(新数值), 后端 game-core 同此,
 * 让离线胜率 ≈ 在线每境稳态 80~95% 而非旧"中值怪+固定4%翻车" */
function offlineFightWin(big) {
  const lv = (state.realmIdx || 0) + 1, eb = equipBonus();
  const hs = finalStats({ hp: 100 + 330 * lv, atk: 10 + 46 * lv, def: 5 + 26 * lv },
    { hp: eb.hp || 0, atk: eb.atk || 0, def: eb.def || 0 }, eb.agg);
  const mon = genMonster(big, lv);                        // 同在线同式(含词缀妖兽)
  const ms = finalStats({ hp: mon.hp, atk: mon.atk, def: mon.def }, {}, fxAgg(mon.fx ? [mon] : []));
  let mhp = ms.hp, hphp = hs.hp, round = 0;
  while (true) {
    round++;
    const sh = tryStrike(hs.atk, hs, ms.def, ms.dodge);   // 玩家出手(会心/暴击/破甲同在线)
    if (!sh.miss) { mhp -= sh.dmg; if (mhp <= 0) return true; }
    const sf = tryStrike(ms.atk, ms, hs.def, hs.dodge);   // 妖兽还手
    if (!sf.miss) { hphp -= sf.dmg; if (hphp <= 0) return false; }
    if (round > 300) return hphp > mhp;
  }
}
function huntTxtOf(H) {                 // 离线巡猎纪要(云端 gains.hunt / 本地兜底 共用)
  if (!H || !H.waves) return "";
  const kN = H.keptCount != null ? H.keptCount : (Array.isArray(H.kept) ? H.kept.length : (H.kept || 0));
  const kName = H.keptName || (Array.isArray(H.kept) && H.kept.length ? H.kept[0].name : "");
  return `<br><br><span style="color:#f0c98a">主身巡猎 ${H.waves} 波</span>：斗法 ${H.fights} 场（胜 ${H.wins} · 负 ${H.loses}）、秘境 ${H.mysts} 处<br>` +
    `斩获修为 +<span class="num"> ${fmt(H.exp || 0)}</span>、灵石 +<span class="num"> ${fmt(H.spirit || 0)}</span>` +
    (kN ? `<br>阿青收下 <b>${kN}</b> 件新宝${kName ? `（${kName} 等）` : ""}，藏宝阁在架 ${H.equipped || kN} 件` : "") +
    (H.melted ? `；余下 <b>${H.melted}</b> 件不入眼，尽数投炉熔作灵石 +<span class="num"> ${fmt(H.meltSp || 0)}</span>` : "");
}

function closeOffline() { $("offlineModal").classList.remove("show"); }

/* ============ 背景与特效层 ============ */
/* 灵力辉光层: 动态载入 fx2d.js, 挂一层 canvas 到角色容器(与立绘同频呼吸) */
function initFxLayer() {
  const cult = document.getElementById("cult");
  if (!cult || document.getElementById("cultFx")) return;
  const cv = document.createElement("canvas");
  cv.id = "cultFx";
  cv.style.cssText = "position:absolute;left:0;top:0;width:100%;height:100%;"
    + "pointer-events:none;z-index:3;animation:breath 4.6s ease-in-out infinite";
  cult.appendChild(cv);
  import("./fx2d.js?v=" + CACHE_VER)
    .then(m => { try { m.initFx(cv); } catch (e) { console.error("[fx2d] init:", e); } })
    .catch(e => console.error("[fx2d] load:", e));
}
/* 特效诊断浮层: 引擎错误/降级模式直接显示, 便于排查 */
function initFxDiag() {
  try {
    let pill = document.getElementById("fxDiag");
    if (!pill) {
      pill = document.createElement("div");
      pill.id = "fxDiag";
      pill.style.cssText = "position:fixed;top:10px;left:50%;transform:translateX(-50%);z-index:99;"
        + "max-width:86vw;background:rgba(120,20,20,.92);color:#ffd7d7;font-size:11px;"
        + "padding:6px 12px;border-radius:999px;display:none;pointer-events:none";
      document.body.appendChild(pill);
    }
    const show = msg => {
      pill.textContent = msg; pill.style.display = "block";
      clearTimeout(pill._t); pill._t = setTimeout(() => { pill.style.display = "none"; }, 6000);
    };
    window.addEventListener("error", e => show("运行错误: " + (e.message || e.type)));
    setInterval(() => {
      if (window.__fxMode === "2d") { show("特效模式: 2D 兜底 (WebGL不可用)"); window.__fxMode = null; }
      if (window.__fxErr) { show("特效错误: " + window.__fxErr); window.__fxErr = null; }
    }, 3500);
  } catch (e) { console.warn(e); }
}

async function initBg() {
  try { await initBg2D(); }
  catch (e) { console.warn("背景初始化失败，CSS 兜底", e); document.body.classList.add("no-webgl"); }
}
/* v1.7.20: bg.js 已重写为纯 Canvas 2D(无 WebGL/无 Three), 移动端低端机更稳 */
async function initBg2D() {
  const canvas = $("bg");
  const mod = await import("./bg.js?v=" + CACHE_VER);
  window.__bgCtrl = await mod.initDeepSpace(canvas);
}
/* v1.7.20 PERF-2: 渲染 DPR 自适应 —— 触屏/小内存低端设备收敛到 1.5(帧缓冲像素约 -44%), 桌面保留 2 */
function capDeviceDpr() {
  let low = false;
  try { low = matchMedia("(pointer: coarse)").matches; } catch (e) {}
  try { if (navigator.deviceMemory && navigator.deviceMemory <= 4) low = true; } catch (e) {}
  return Math.min(window.devicePixelRatio || 1, low ? 1.5 : 2);
}
/* v1.6.0-B 灵气道场叠加层: 随大境界变色调的流动云雾 + 上升灵气粒子(叠在背景之上) */
const AURA_COLORS = [
  [103,201,171], [103,201,171], [91,143,214], [233,196,126],
  [180,138,214], [207,232,224], [207,232,224]
];
let _auraCv, _auraCtx, _auraP = [], _auraT = 0, _auraColor = AURA_COLORS[0].slice(), _auraAcc = 0;
const AURA_FPS = 30;   // v2.3 PERF: 灵气层限帧 30fps(与 fx2d 统一), 每帧 4 径向渐变+36 粒子在 60fps 下是持续耗电大头
function auraColorNow() { return AURA_COLORS[Math.min(bigIdx(), AURA_COLORS.length - 1)]; }
function initAura() {
  _auraCv = $("aura"); if (!_auraCv) return;
  _auraCtx = _auraCv.getContext("2d");
  const fit = () => {
    const dpr = capDeviceDpr();                    // v1.7.20 PERF-2: 低端收敛
    _auraCv.width = innerWidth * dpr; _auraCv.height = innerHeight * dpr;
    _auraCtx.setTransform(dpr, 0, 0, dpr, 0, 0);
  };
  fit(); addEventListener("resize", fit);
  for (let i = 0; i < 36; i++)
    _auraP.push({ x: Math.random()*innerWidth, y: Math.random()*innerHeight, r: 1+Math.random()*2.4, s: 8+Math.random()*22, a: .25+Math.random()*.5, ph: Math.random()*7 });
}
function tickAura(dt) {
  if (!_auraCtx) return;
  _auraAcc += dt;
  if (_auraAcc < 1 / AURA_FPS) return;          // 限帧 30fps: 不足一帧间隔直接跳过(粒子位置用累计 realDt 补偿, 不丢物理)
  const realDt = _auraAcc; _auraAcc = 0;
  _auraT += realDt;
  const W = innerWidth, H = innerHeight, c = auraColorNow();
  for (let i = 0; i < 3; i++) _auraColor[i] += (c[i] - _auraColor[i]) * Math.min(1, realDt * 1.5);
  const [r,g,b] = _auraColor.map(v => Math.round(v));
  _auraCtx.clearRect(0, 0, W, H);
  _auraCtx.globalCompositeOperation = "lighter";
  const blobs = [[.25,.3,.5],[.7,.25,.42],[.5,.7,.55],[.82,.72,.4]];
  for (let i = 0; i < blobs.length; i++) {
    const [bx,by,bz] = blobs[i];
    const cx = (bx + Math.sin(_auraT*0.06 + i)*0.05)*W, cy = (by + Math.cos(_auraT*0.05 + i*1.3)*0.05)*H, rad = bz*Math.min(W,H)*0.6;
    const grd = _auraCtx.createRadialGradient(cx, cy, 0, cx, cy, rad);
    grd.addColorStop(0, `rgba(${r},${g},${b},.07)`); grd.addColorStop(1, `rgba(${r},${g},${b},0)`);
    _auraCtx.fillStyle = grd; _auraCtx.beginPath(); _auraCtx.arc(cx, cy, rad, 0, 7); _auraCtx.fill();
  }
  for (const p of _auraP) {
    p.y -= p.s*realDt; p.x += Math.sin(_auraT*0.6 + p.ph)*6*realDt;
    if (p.y < -10) { p.y = H + 10; p.x = Math.random()*W; }
    const a = p.a * (0.5 + 0.5*Math.sin(_auraT*1.2 + p.ph));
    _auraCtx.fillStyle = `rgba(${r},${g},${b},${a*0.5})`;
    _auraCtx.beginPath(); _auraCtx.arc(p.x, p.y, p.r, 0, 7); _auraCtx.fill();
  }
  _auraCtx.globalCompositeOperation = "source-over";
}

function mainMoment() {
  const pool = MAIN_STORY[Math.min(bigIdx(), MAIN_STORY.length - 1)];
  const g = Math.round(rateNow() * 2.5);
  state.exp += g;
  pushMsg("main", `<span class="b">主线</span>·修为<span class="g">+${fmt(g)}</span>｜${pickNoRepeat(pool, "m" + bigIdx())}`);
}

/* ============ 主循环 ============ */
let _hudAcc = 0;   // v1.7.20 PERF-1: HUD 刷新累计, ≥100ms 才刷一次; 事件触发仍即时刷新
function loop(dt) {
  if (!breaking) {
    /* v1.8.0: 本地这一笔是「预测」—— 只为了让数字看着在涨。计入 _pred, 上传时会被扣掉,
       真正的账由服务端按自己的钟结算。 */
    const _g = rateNow() * dt;
    state.exp += _g; _pred.exp += _g;
    // 小层/同大境自动精进; 每轮重取 realm() —— 修为只可升小段, 遇'圆满'必须停手等手动渡劫(防大额增益一次越过跨大境门槛)
    let guard = 0;
    while (!breaking && state.realmIdx < TOTAL_SEGS - 1 && guard++ < 8) {
      const r = realm();
      if (state.exp < r.need || r.isBigEnd) break;
      state.exp -= r.need;
      state.realmIdx++;
      const nr = realm();
      pushMsg("main", `修为精进 → <span class="g">${nr.big === "炼气" ? "炼气" + cnNum(nr.segNo) + "层" : nr.label}</span>`);
      updateRealmUI();
    }
    realmPlot(); // 到新小层即推进当前卷剧情(跨大境须手动渡劫 → 剧情也绝不越卷)
  }
  tickDsp(dt);
  tickAura(dt);
  _hudAcc += dt; if (_hudAcc >= 0.1) { _hudAcc = 0; updateHUD(); realmPlot(); checkMilestones(); if (Math.random() < 0.035) adventure(); if (Math.random() < 0.006) mainMoment(); }   // PERF-1: HUD ~10FPS; PERF-3: adventure/mainMoment 从每帧 60 次随机检查降到 10fps(概率等价换算: 0.35*0.1 / 0.06*0.1)
  tickBurst(dt);
}

/* ============ 启动 ============ */
/* v1.10.0: 本地档读取迁移到 boot() 开头 await —— load 为同步明文 JSON, 仍极快 */

/* v1.8.0 启动门禁:
 *   打开 → 本地渲染开屏 → 校验联网(顺便请服务端权威结算一次)
 *        成功 → 进游戏;  失败 → 停在失败页, 不进入游戏
 * 只有一条时间线: 服务端。客户端不自己算账, 也不在断网时发钱。 */
async function bootGate() {
  const wait = [0, 1000, 2000, 4000, 8000];
  for (let i = 0; i < wait.length; i++) {
    if (wait[i]) await new Promise(s => setTimeout(s, wait[i]));
    splashStat(i ? `正在重连服务器…（第 ${i} 次）` : "正在连接服务器…");
    let ok = false;
    try { ok = await bootCloud(); } catch (e) { ok = false; }
    if (ok) return true;
  }
  return false;
}

let _hiddenAt = 0;

function startGame() {
  updateRealmUI();
  renderPName();                // v1.7.26 道号显示(默认 6 位数字)
  _dsp.spirit = state.spirit; _dsp.exp = state.exp;
  _floatPrev.spirit = state.spirit; _floatPrev.exp = state.exp;
  updateHUD();
  updateArts();
  realmPlot(); // 按当前境界推进已及剧情
  {
    const o0 = PLOT[0] && PLOT[0][0];
    if (o0 && state.journal.length && !journalHasKey(o0) && bigIdx() > 0) {
      addJournal({ key: o0.key, big: o0.big, kind: o0.kind, title: o0.title, text: o0.text }); // 老档补记起点
    }
  }
  setInterval(save, 30000);   // v2.3 PERF: 自动存档 8s→30s(pagehide/visibilitychange 已保证退出即存, 挂机期 30s 足够防崩溃丢档)
  /* v1.9.9d 法宝图标空闲预热解码(4 部位×6 品质 24 张 webp):
     安卓 WebView 首开法宝窗才现解码 4 张图, 与弹窗全卡首光栅化同帧挤爆 → 开窗卡死/掉帧闪屏;
     启动低谷期逐张 decode() 预热, 开窗只剩合成 */
  setTimeout(() => {
    ["w", "a", "p", "s"].forEach(si => { for (let q = 0; q < 6; q++) {
      const im = new Image();
      im.src = "assets/modals/art-ico/" + si + q + ".webp";
      try { im.decode && im.decode().catch(() => {}); } catch (e) {}
    } });
  }, 4000);
  addEventListener("pagehide", () => { save(); cloudFlush(); });
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "hidden") {
      _hiddenAt = srvNow();
      save(); cloudFlush();     // 记下"我在场", 并同步一次
    } else if (_hiddenAt && srvNow() - _hiddenAt > 30000) {
      /* v1.8.0 切后台超 30 秒 → 一律当离线, 回前台强制刷新。
       * 刷新后重走门禁, 服务端按 [上次写入时刻, now] 结算离线收益并弹面板。
       * 好处: 客户端不需要维护任何"欠账 / 区间 / 基准"状态, 整条链路只剩一条线。 */
      location.reload();
    } else {
      cloudSettle();            // 短时切走: 补一次结算即可(服务端按 ≤180s 判为在线, 满速率)
    }
  });
  cloudInit();                  // 云存档面板交互 + 断网恢复
  startHeartbeat();             // v1.8.0 周期心跳(90s)
  setInterval(stayMailCheck, 60000);   // 在线寄包: iOS 常驻标签页也能收到化身手札
  initAura();
  initBg();
  initFxDiag();
  initFxLayer();
  let lastLoop = performance.now();
  (function main() {
    const now = performance.now();
    const dt = Math.min(.1, (now - lastLoop) / 1000); lastLoop = now;
    loop(dt);
    requestAnimationFrame(main);
  })();
}

async function boot() {
  load();                      // v1.10.0: 先读本地档(明文 JSON 同步), 再走云端门禁
  let passed = false;
  try { passed = await bootGate(); } catch (e) { passed = false; }
  if (!passed) { splashFail(); return; }   // 连不通 → 停在失败页, 不进入游戏
  await splashFinish();                    // v1.9.1: 开屏彻底退场后才初始化主页(resolve 与 startGame 同一微任务链, 中间不会被渲染)
  startGame();
}
setTimeout(boot, 0);   // 放到下一 tick: 等开屏控制函数(splashStat/Finish/Fail)就位

/* 调试句柄(便于测试/调参) */
window.__game = {
  get state() { return state; },
  /* v1.8.0 调试句柄 */
  get srvOffset() { return _srvOffset; },
  get rate() { return _rate; },
  get pred() { return _pred; },
  get syncAt() { return _syncAt; },
  srvNow: () => srvNow(),
  settle: () => cloudSettle(),
  hbFail: () => hbFail(),
  hbOk: () => hbOk(),
  setRealm: i => { state.realmIdx = i; state.exp = 0; updateRealmUI(); updateHUD(); },
  giveExp: n => { state.exp += n; updateHUD(); },
  giveSpirit: n => { state.spirit += n; updateHUD(); },
  adventure: () => adventure(),
  mainMoment: () => mainMoment(),
  makeArt: () => makeArt(),
  updateArts: h => updateArts(h),
  realmPlot: () => realmPlot(),
  openStory, pushMsg, save, load,
};


/* ==================== P0 分身云游 ==================== */
function zoneOfBig(bi) { const z = ZONES[bi]; return z ? z : ZONES[ZONES.length - 1]; }
function zoneOfLoc(id) { for (const z of ZONES) if (z.locs.some(l => l.id === id)) return z; return null; }
function locById(id) { for (const z of ZONES) { const l = z.locs.find(x => x.id === id); if (l) return l; } return null; }
function pickLoc() { const z = zoneOfBig(bigIdx()); return { z, l: z.locs[(Math.random() * z.locs.length) | 0] }; }
function durTxt(sec) {
  if (sec >= 86400) { const d = Math.round(sec / 86400 * 10) / 10; return (d % 1 === 0 ? d : d.toFixed(1)) + " 天"; }
  if (sec >= 3600) return Math.round(sec / 3600) + " 时辰";
  return Math.max(1, Math.round(sec / 60)) + " 分钟";
}
function travelBtnLbl() {
  const b = $("btnTravel"); if (!b) return;
  const lb = b.querySelector(".label"); if (!lb) return;
  if (state.travel) {
    const l = locById(state.travel.loc);
    lb.innerHTML = "云游中";
    b.classList.add("traveling");
    b.title = l ? "化身正于 " + l.n : "化身在外游历";
  } else { lb.innerHTML = "云游"; b.classList.remove("traveling"); b.title = ""; }
}
function travelAvatarHTML() {
  if (state.travel) {
    const l = locById(state.travel.loc);
    const awaySec = Math.max(0, Math.floor((srvNow() - state.travel.since) / 1000));
    /* v1.9.0 面板: 不再有「召回」—— 化身何时回山由信决定。
     * 这里呈现的是「已发几封 / 还要多久下一封 / 何时自动归来」。 */
    const sent = Math.min(travelSent(), travelMailCount(awaySec));
    const want = travelMailCount(awaySec);
    const inFirst = awaySec < TRAVEL_FIRST_WINDOW;
    const backAt = TRAVEL_FIRST_WINDOW;                       // 满 8 封(4 小时)即归来
    const backIn = Math.max(0, backAt - awaySec);
    const nextIn = travelNextMailIn(awaySec);
    const capped = awaySec >= TRAVEL_SPAN;
    const mailLeft = MAIL_CAP - (state.mails || []).length;
    /* 发信节奏说明 */
    const pace = inFirst
      ? `每 <b>30 分钟</b> 一封（前八封）`
      : `每 <b>2 小时</b> 一封（第八封之后）`;
    const nextTxt = capped
      ? `<span style="color:#8fd8bd">已在外满两日，信不再增，化身就此回山。</span>`
      : nextIn == null
        ? `<span style="color:#8fd8bd">八封已足，上线即可收化身回山。</span>`
        : `下一封还需 <b style="color:#c9b98a">${durTxt(nextIn)}</b>`;
    const backTxt = cld.ready
      ? (awaySec >= backAt
          ? `<span style="color:#8fd8bd">已够八封，下次上线化身便自行回山。</span>`
          : `再在外 <b style="color:#c9b98a">${durTxt(backIn)}</b> 满八封，届时上线即自行归来。`)
      : `<span style="color:#8b94a8">云端未就绪，归来判定以服务端为准。</span>`;
    /* 进度: 0..8 封(前段)；超出后段就用"距两日"的进度 */
    const prog = inFirst ? Math.min(8, sent) / 8 : Math.min(1, (awaySec - TRAVEL_FIRST_WINDOW) / (TRAVEL_SPAN - TRAVEL_FIRST_WINDOW));
    const progPct = Math.round(prog * 100);
    const mailWarn = mailLeft <= 0
      ? `<div style="color:#e08a6a;font-size:11px;margin-top:6px">信匣已满 <b>${MAIL_CAP}</b> 封 —— 化身暂时停笔，拆几封它便续上。</div>`
      : mailLeft <= 5
        ? `<div style="color:#c9b98a;font-size:11px;margin-top:6px">信匣余 <b>${mailLeft}</b> 封空位。</div>`
        : "";
    return `<div style="text-align:center;padding:14px 4px">
        <div style="font-family:var(--font-brush);font-size:18px;color:#d8b06a;letter-spacing:.12em">化身在${l ? l.n : "远方"} · ${durTxt(awaySec)}</div>
        <p style="color:#a7b0c4;margin-top:10px;line-height:1.9">化身在外游历，${pace}。已寄回 <b style="color:#c9b98a">${sent}</b> 封手札。<br>满 <b style="color:#c9b98a">八封</b>（四个时辰）化身便自行回山，<b style="color:#c9b98a">无从召回</b>——它在外的所得，全在信里。</p>
        <div style="height:4px;background:rgba(201,168,106,.14);margin:11px 18px 0">
          <i style="display:block;height:100%;width:${Math.min(100, progPct)}%;background:linear-gradient(90deg,rgba(201,168,106,.55),rgba(232,197,107,.95))"></i>
        </div>
        <p style="color:#8b94a8;font-size:11.5px;margin-top:8px;line-height:1.7">${nextTxt}</p>
        <div style="text-align:left;margin:10px 10px 0;padding:9px 11px;background:rgba(201,168,106,.07);border:1px dashed rgba(201,168,106,.22)">
          <div style="font-size:11px;color:#8b94a8;letter-spacing:.04em">归山 · 由信而定</div>
          <div style="font-size:12.5px;color:#c9b98a;margin-top:5px;line-height:1.8">${backTxt}</div>
          ${mailWarn}
        </div>
        <button class="btn" style="margin-top:12px" onclick="openMail()"><svg class="skin" viewBox="0 0 200 60" preserveAspectRatio="none"><path class="ink" d="M12 9 C28 3 44 10 60 6 C76 2 92 8 108 6 C124 4 140 8 158 6 C174 4 192 8 197 16 C199 26 198 34 195 41 C193 46 196 52 182 53 C168 55 154 50 140 53 C124 56 110 50 96 53 C82 56 68 51 56 53 C42 55 30 50 20 52 C8 54 2 46 3 38 C3 28 2 20 5 15 C7 12 9 10 12 9 Z"/></svg><span class="label">去拆信 · 已收 ${(state.mails || []).length} 封</span></button>
        <div style="font-size:10.5px;color:#6d7688;margin-top:8px">开炉炼丹与服丹，请去左上角 <b style="color:#a98a5a">丹</b> 房。</div></div>`;
  }
  const z = zoneOfBig(bigIdx());
  const placeNames = z.locs.map(x => x.n).join("、");
  return `<div style="padding:10px 4px 14px;text-align:center;border-bottom:1px dashed rgba(201,168,106,.16)">
      <div style="font-family:var(--font-brush);font-size:16px;color:#d8b06a;letter-spacing:.06em">${z.name}</div>
      <p style="color:#8b94a8;font-size:11.5px;margin-top:6px;line-height:1.9">化身会顺着自己的心意，在 ${placeNames} 一带游历。<br>在外每满 <b style="color:#a98a5a">30 分钟</b> 寄回一封手札，八封（四个时辰）后<b style="color:#a98a5a">自行回山</b>；若你久不归来，它便放慢到<b style="color:#a98a5a">每 2 小时</b>一封，最多在外守候 <b style="color:#a98a5a">两日</b>。</p>
      <button class="btn" style="margin-top:10px" onclick="startTravel()"><svg class="skin" viewBox="0 0 200 60" preserveAspectRatio="none"><path class="ink" d="M12 9 C28 3 44 10 60 6 C76 2 92 8 108 6 C124 4 140 8 158 6 C174 4 192 8 197 16 C199 26 198 34 195 41 C193 46 196 52 182 53 C168 55 154 50 140 53 C124 56 110 50 96 53 C82 56 68 51 56 53 C42 55 30 50 20 52 C8 54 2 46 3 38 C3 28 2 20 5 15 C7 12 9 10 12 9 Z"/></svg><span class="label">遣化身出门</span></button>
    </div>
    <div style="font-size:10.5px;color:#6d7688;text-align:center;padding:10px 4px;line-height:1.8">拾得的药草与丹方残页都装在<b style="color:#a98a5a">鸿雁信匣</b>里，拆开才算你的。<br>信匣最多存 <b style="color:#a98a5a">${MAIL_CAP}</b> 封，满了化身就停笔。</div>`;
}
/* v1.7.22: 炼丹独立成【丹房】(原嵌在云游面板内) —— 材料/丹药/开炉集中于此 */
function matBagHTML() {
  const own = Object.keys(MATS).filter(k => ((state.mats || {})[k] || 0) > 0);
  if (!own.length) return `<div class="al-sec">行囊 · 手头材料</div><div class="al-empty">行囊空空——遣化身出门云游，可捎回药草灵石。</div>`;
  const chips = own.map(k => `<span class="al-bagchip" title="${MATS[k].n} · ${MATS[k].src}">${MATS[k].n}<b>×${state.mats[k]}</b><i class="t">${MATS[k].t}</i></span>`).join("");
  return `<div class="al-sec">行囊 · 手头材料 <i>尚未采到的不在此列</i></div><div class="al-bag">${chips}</div>`;
}
function pillCabinetHTML() {
  const pk = Object.keys(state.pills || {}).filter(id => RECIPES[id]);
  if (!pk.length) return `<div class="al-sec">丹药匣</div><div class="al-empty">尚无丹药——材料齐了即可开炉。</div>`;
  const row = pk.map(id => {
    const rp = RECIPES[id];
    const fn = rp.d.split("：").pop();          // v1.9.9: 服用信息(效果摘要), 图标下方两行截断
    return `<span class="al-pill" title="${rp.d}">${pillIco(id, 44)}<span class="nm">${rp.n}</span><span class="fx">${fn}</span><b>×${state.pills[id]}</b><button class="take" onclick="consumePill('${id}')">服</button></span>`;
  }).join("");
  return `<div class="al-sec">丹药匣 <i>点“服”即用</i></div><div class="al-grid">${row}</div>`;
}
function openTravel() {
  const m = $("travelModal"); if (!m) return;
  const box = $("travelBody"); if (!box) return;
  box.innerHTML = travelAvatarHTML();
  m.classList.add("show");
  travelBtnLbl();
}
function closeAlchemy() { const m = $("alchemyModal"); if (m) m.classList.remove("show"); }
/* ==================== v1.9.8 丹房工程化工作台 ====================
 * 左炉右囊: 点囊入炉 → 点丹方卡自动配料(可炼才可见) → 炼制 → 丹药匣服丹。
 * 与 alch-lab2 定稿一字同构; 材料图标定稿 assets/modals/ico/{key}.webp 铺满色块, 加载失败 remove() 回退首字色块。 */
let cauldron = {}, selRecipe = null;                    // 炉内材料 / 当前选中方(关弹窗不清, 重开仍在)
const alHave = m => (state.mats || {})[m] || 0;
const alInFurn = m => cauldron[m] || 0;
const alIcoCls = t => t === "兽材" ? "beast" : (t === "灵液" || t === "仙泉" || t === "仙晶") ? "liquid" : "plant";
const alIco = (m, sz) => `<span class="ico ${alIcoCls(MATS[m].t)}"${sz ? ` style="width:${sz}px;height:${sz}px;font-size:${Math.round(sz * .45)}px"` : ""}><img class="icoim" src="assets/modals/ico/${m}.webp" alt="" onerror="this.remove()">${MATS[m].n[0]}</span>`;
/* v1.9.9 成品丹图片图标: 39 味丹药全量 webp(首字色块兜底), pillbg 棕金底与丹房同源 */
const pillIco = (id, sz) => `<span class="ico pillbg"${sz ? ` style="width:${sz}px;height:${sz}px;font-size:${Math.round(sz * .45)}px"` : ""}><img class="icoim" src="assets/modals/ico/${id}.webp" alt="" onerror="this.remove()">${RECIPES[id].n[RECIPES[id].n.length - 2] || "丹"}</span>`;
const recipeCan = id => Object.keys(RECIPES[id].need).every(m => alHave(m) >= RECIPES[id].need[m]);
function renderFurn() {
  const el = $("furnSlots"); if (!el) return;
  const mids = Object.keys(cauldron).filter(m => cauldron[m] > 0);
  let h = mids.map(m => `<div class="slot" title="${MATS[m].n} · 点之退回" onclick="takeMat('${m}')">
      ${alIco(m, 34)}<b>×${cauldron[m]}</b></div>`).join("");
  for (let i = mids.length; i < 3; i++) h += `<div class="slot"><em>空</em></div>`;
  el.innerHTML = h;
}
function renderBag() {
  const nEl = $("bagN"), el = $("bagGrid"); if (!el) return;
  const own = Object.keys(MATS).filter(m => alHave(m) > 0);
  if (nEl) nEl.textContent = `${own.length} / ${Object.keys(MATS).length}`;
  let h = own.map(m => `<div class="cell" title="${MATS[m].n} · ${MATS[m].src}" onclick="putMat('${m}')">
      ${alIco(m)}<b>×${alHave(m) - alInFurn(m)}</b></div>`).join("");
  const pad = (3 - own.length % 3) % 3;
  for (let i = 0; i < pad + 3; i++) h += `<div class="cell empty"><em>空</em></div>`;
  el.innerHTML = h;
}
function renderRecipes() {
  const el = $("rpList"); if (!el) return;
  const bi = bigIdx();
  const ok = Object.keys(RECIPES).filter(id => {
    const rp = RECIPES[id];
    if (rp.big > bi) return false;                        // 境界未至不示
    if (rp.h && !hiddenUnlocked(rp.big)) return false;    // 残卷未齐不示
    return recipeCan(id);                                 // 材料齐则现
  });
  el.innerHTML = ok.length ? ok.map(id => {
    const rp = RECIPES[id];
    const need = Object.keys(rp.need).map(m => `${MATS[m].n}${rp.need[m]}`).join(" · ");
    const fn = rp.d.split("：").pop();                    // 只展示功能: 取「:」后段
    return `<div class="rp-card${selRecipe === id ? " sel" : ""}" title="${rp.n} · ${rp.d}｜需 ${need}" onclick="loadRecipe('${id}')">
      <div class="rp-ico"><img class="icoim" src="assets/modals/ico/${id}.webp" alt="" onerror="this.remove()">${rp.n[rp.n.length - 2] || "丹"}</div>
      <div class="rp-bd"><span class="nm">${rp.n}</span><span class="ds">${fn}</span></div>
      <div class="rp-arrow">${selRecipe === id ? "在炉" : "入炉"}</div></div>`;
  }).join("") : `<div class="al-empty" style="border:1px dashed rgba(201,168,106,.16);border-radius:10px;padding:13px;text-align:center;font-style:normal">
    <b style="font-size:12px;color:#8b94a8;letter-spacing:2px;font-weight:normal">暂 无 可 炼 丹 方</b></div>`;
}
function renderCabinet() {
  const wrap = $("cabWrap"), el = $("cabGrid"); if (!el) return;
  const pk = Object.keys(state.pills || {}).filter(id => RECIPES[id] && state.pills[id] > 0);
  if (wrap) wrap.style.display = pk.length ? "" : "none";
  el.innerHTML = pk.map(id => {
    const rp = RECIPES[id];
    const fn = rp.d.split("：").pop();          // v1.9.9: 服用信息行
    return `<div class="pillb" title="${rp.d}" onclick="consumePill('${id}')">
      ${pillIco(id)}<span class="nm">${rp.n}</span><span class="fx">${fn}</span><b>×${state.pills[id]}</b><em>服</em></div>`;
  }).join("");
}
function fitsRecipe() {
  if (!selRecipe) return false;
  const need = RECIPES[selRecipe].need, ks = Object.keys(need);
  return ks.every(m => alInFurn(m) === need[m]) && Object.keys(cauldron).filter(m => cauldron[m] > 0).length === ks.length;
}
function renderCraftBtn() {
  const b = $("craftBtn"); if (!b) return;
  b.disabled = !(selRecipe && fitsRecipe());
}
function renderAlch() { renderFurn(); renderBag(); renderRecipes(); renderCabinet(); renderCraftBtn(); }
/* v1.10.1: 点击报材料名 —— 移动端没有 title 悬停, 点背包格/炉内格时浮注显示 名字 · 类型 · 来源, 1.5s 自淡 */
let alTipT = 0;
function alTip(id, m) {
  const el = $(id), M = MATS[m];
  if (!el || !M) return;
  el.innerHTML = `<b>${M.n}</b><i>${M.t} · ${M.src}</i>`;
  el.classList.add("on");
  clearTimeout(alTipT);
  alTipT = setTimeout(() => el.classList.remove("on"), 1500);
}
function putMat(m) {
  if (alHave(m) - alInFurn(m) <= 0) return;
  cauldron[m] = alInFurn(m) + 1;
  if (selRecipe && !fitsRecipe()) selRecipe = null;
  renderAlch();
  alTip("bagTip", m);
}
function takeMat(m) {
  if (!cauldron[m]) return;
  cauldron[m]--; if (!cauldron[m]) delete cauldron[m];
  if (selRecipe && !fitsRecipe()) selRecipe = null;
  renderAlch();
  alTip("furnTip", m);
}
function loadRecipe(id) {
  if (!recipeCan(id)) { pushMsg("main", "材料不齐，丹炉难以为继"); return; }
  selRecipe = selRecipe === id ? null : id;
  cauldron = {};
  if (selRecipe) for (const m in RECIPES[id].need) cauldron[m] = RECIPES[id].need[m];
  renderAlch();
}
function doCraft() { if (selRecipe && fitsRecipe()) craftPill(selRecipe); }
function openAlchemy() {
  const m = $("alchemyModal"); if (!m) return;
  renderAlch();
  m.classList.add("show");
}
/* consumePill/craftPill 后只刷新当前打开的面板 */
function refreshOpenPanel() {
  const am = $("alchemyModal"), tm = $("travelModal");
  if (am && am.classList.contains("show")) openAlchemy();
  else if (tm && tm.classList.contains("show")) openTravel();
}
function closeTravel() { const m = $("travelModal"); if (m) m.classList.remove("show"); }
function startTravel() {
  if (state.travel) { pushMsg("main", "化身尚在云游，去行迹条看看它走到哪了"); closeTravel(); return; }
  const { l } = pickLoc();
  /* v1.9.0: 派发时记录 sent=0(已发封数游标) —— 服务端据此补齐信匣, 天然幂等 */
  state.travel = { loc: l.id, since: Date.now(), sent: 0 };
  _encNext = autoHuntOn() ? Date.now() + searchMs() : 0;   // 重置巡猎: 自动斗法开则重新起算搜寻
  pushMsg("main", `你为化身备好行囊。它往<span class="r">${l.n}</span>的方向去了，阿青蹲在门口目送，尾巴搭在你脚边。`);
  pushMsg("avatar", `阿青送化身到山门口，回来在你蒲团边卧下`);
  pushMsg("main", `<span class="b">化身在外每满 30 分钟寄回一封手札</span>，满八封（四个时辰）便自行回山。<br>记得常去右上角鸿雁处拆信——信里的东西，隔着匣子不算你的。`);
  travelBtnLbl(); traceRefresh(); updateHUD(); save(); cloudSoon();
  closeTravel();
}
/* ==================== v1.9.0 云游计时寄信制 ====================
 * 第一性原理: 云游的产出 = 化身寄回的信。信的数量由「在外时长」线性决定。
 *
 *   在线/离线前段: 每 30 分钟一封, 共 8 封(= 4 小时)
 *   之后(仍在离线) : 每 2 小时一封
 *   总时长硬顶     : 48 小时(离线两天)
 *
 * 归来: 只由「玩家上线时的服务端结算」判定 —— 在外满 4 小时(8 封)即自行回山, 空手而归
 *       (产出早在信里)。玩家不再有「召回」按钮: 化身何时回来由信决定, 不由玩家点。
 *
 * 为什么删掉「召回」: 旧版召回是"随时把一个游历周期兑现"的入口, 派发→立刻召回
 *   能反复刷出保底材料(TRAVEL_TAU 曲线 + max(1,…) 保底 = 无限刷)。信匣制下
 *   唯一产出通道是信, 而信由时钟决定, 这条路径从根上不存在了。
 *
 * 本段与服务端 game-core.js 的 travelMailCount 同式, 前端只做「预测/展示」。
 */
const MAIL_CAP = 50;                       // 信匣容量(与 game-core.js 一致)
const TRAVEL_FIRST_STEP = 1800;            // 前段: 30 分钟一封
const TRAVEL_FIRST_WINDOW = 4 * 3600;      // 前段总窗口: 4 小时 → 8 封
const TRAVEL_FIRST_MAX = 8;                // 前段封数
const TRAVEL_LATE_STEP = 7200;             // 后段: 2 小时一封
const TRAVEL_SPAN = 48 * 3600;             // 在外硬顶: 48 小时
const TRAVEL_SPAN_MAILS = 30;              // 48 小时共得封数(8 + 22)
/* 在外 awaySec 秒 → 应得封数(与 game-core.travelMailCount 完全同式) */
function travelMailCount(awaySec) {
  const t = Math.max(0, Math.min(+awaySec || 0, TRAVEL_SPAN));
  const fast = Math.min(t, TRAVEL_FIRST_WINDOW);
  const slow = Math.max(0, t - TRAVEL_FIRST_WINDOW);
  return Math.floor(fast / TRAVEL_FIRST_STEP) + Math.floor(slow / TRAVEL_LATE_STEP);
}
/* 已发封数(本地读 travel.sent, 服务端权威值会在心跳时覆盖回来) */
function travelSent() {
  const t = state.travel;
  if (!t) return 0;
  return Math.max(0, Math.floor(t.sent || 0));
}
/* 下一封还要多久(秒); 已满 8 封且在外 → 返回 null(等上线归来) */
function travelNextMailIn(awaySec) {
  const t = Math.max(0, Math.min(+awaySec || 0, TRAVEL_SPAN));
  if (t >= TRAVEL_SPAN) return null;
  const n = travelMailCount(t);
  const at = travelSecForMails(n + 1);
  return Math.max(0, at - t);
}
function travelSecForMails(n) {
  if (n <= 0) return 0;
  if (n <= TRAVEL_FIRST_MAX) return n * TRAVEL_FIRST_STEP;
  return TRAVEL_FIRST_WINDOW + (n - TRAVEL_FIRST_MAX) * TRAVEL_LATE_STEP;
}

/* ==================== v1.9.0 丹方 buff: 可累加, 封顶 24 小时 ====================
 * 上一版(时间加权)的问题是"吃十道丹与吃一道丹在长离线里几乎一样", 服丹失去意义。
 * 现在改成累加: 每服一道, 把药力时长往后叠; 总时长封顶 24 小时, 到顶后该丹禁止再服。
 *   · 短时丹药在长离线里不再被摊薄(叠得起来就全程生效);
 *   · 但总量有硬顶 —— 最多覆盖 24 小时, 服务端 sanitize 同步钳制, 刷不出通胀。
 * 相冲规则不变: buffMult 仍取"当前最强的一道"(不叠乘), 累加只作用于时长。 */
const BUFF_CAP_MS = 24 * 3600 * 1000;
/* 某种 buff 还剩多少"未来药力"(毫秒)。
 * 语义修正: 只算尚未到期的那一段 —— 已流逝的药力不该继续占额度。
 * 多段按并集去重(重叠不重复计), 与 pushBuff 的"往后叠"保持一致。 */
function buffSpanMs(mult) {
  const now = Date.now();
  const segs = [];
  for (const b of (state.buffs || [])) {
    if (b.mult !== mult) continue;
    const s = Math.max(now, b.start || now), e = b.until || 0;
    if (e > s) segs.push([s, e]);
  }
  if (!segs.length) return 0;
  segs.sort((a, b) => a[0] - b[0]);
  let total = 0, cs = segs[0][0], ce = segs[0][1];
  for (let i = 1; i < segs.length; i++) {
    const [s, e] = segs[i];
    if (s > ce) { total += ce - cs; cs = s; ce = e; }
    else if (e > ce) ce = e;
  }
  return total + (ce - cs);
}
function buffAtCap(mult) { return buffSpanMs(mult) >= BUFF_CAP_MS - 1000; }
/* 累加一道 buff: 从"当前到期时刻"或"现在"取较晚者往后叠, 总长不超 24h */
function pushBuff(mult, durSec) {
  const now = Date.now();
  let end = now;
  for (const b of (state.buffs || [])) if (b.mult === mult && (b.until || 0) > end) end = b.until;
  const until = Math.min(end + durSec * 1000, now + BUFF_CAP_MS);
  if (until <= now) return false;
  state.buffs.push({ mult, start: now, until });
  return true;
}
function consumePill(id) {
  const rp = RECIPES[id]; if (!rp) return;
  if (!state.pills || !state.pills[id]) return;
  const now = Date.now(); const e = rp.eff;
  /* v1.9.0: 增益类丹药到顶(累计 24 小时)就不再允许服用 —— 提示而非静默失败 */
  if ((e.k === "buff" || e.k === "grand") && buffAtCap(e.mult)) {
    pushMsg("main", `<span class="b">药力已至上限</span>：此丹药力已积满 <b>24 时辰</b>，再服无益，且待药力散去。`);
    renderPillHints();
    return;
  }
  state.pills[id]--;
  if (state.pills[id] <= 0) delete state.pills[id];
  /* v1.8.4: buff 记 start ✅ —— 服务端按"有效时段"计 */
  if (e.k === "buff") { pushBuff(e.mult, e.dur); pushMsg("main", `药力化开，周天运转如飞${buffHintOf(e.mult)}`); }
  else if (e.k === "inst") { const gg = rateNow() * e.sec; state.exp += gg; pushMsg("main", `药力化开，修为<span class="g">+${fmt(gg)}</span>`); }
  else if (e.k === "grand") { const gg = rateNow() * e.sec; state.exp += gg; pushBuff(e.mult, e.dur); pushMsg("main", `感悟天劫真意，修为<span class="g">+${fmt(gg)}</span>，道韵萦绕${buffHintOf(e.mult)}`); }
  else if (e.k === "offline") { state.offlineBoostUntil = Math.max(state.offlineBoostUntil || 0, now + e.dur * 1000); pushMsg("main", "洗髓伐脉，此后离线游历更有所得"); }
  updateHUD(); save(); cloudSoon(); refreshOpenPanel(); renderPillHints();
}
/* 服用后附一句剩余药力, 让"累加到顶"这件事对玩家可见 */
function buffHintOf(mult) {
  const left = BUFF_CAP_MS - buffSpanMs(mult);
  if (left <= 60000) return `（药力已积满 24 时辰）`;
  return `（药力共余 ${durTxt(Math.round(left / 1000))}）`;
}
function renderPillHints() {
  const now = Date.now();
  const n = (state.buffs || []).length;
  const o = (state.offlineBoostUntil || 0) > now;
  const el = $("pillHints");
  /* v1.9.0: 附一句药力剩余时长, 让"累加到 24 时辰封顶"这件事可见 */
  let spanTxt = "";
  if (n) {
    const mm = buffMult();
    const left = BUFF_CAP_MS - buffSpanMs(mm);
    spanTxt = left <= 60000 ? "·已满" : "·余" + durTxt(Math.round(left / 1000));
  }
  if (el) el.innerHTML = (n ? `<span style="color:#f0c98a">丹力正盛 ×${buffMult().toFixed(1)}${spanTxt}</span>` : "") +
    (o ? (n ? " · " : "") + `<span style="color:#8fd8bd">洗髓·离线+30%</span>` : "");
}

/* P0 启动引导 */
travelBtnLbl();
renderPillHints();
mailDot();


/* ==================== P1 炼丹炉（v2 丹方体系） ==================== */
/* ==================== v0.8.0 丹方残页 ==================== */
const PAGE_RATE = 0.25;      // 每趟云游带回残页概率(前后端一致)
function pagesOf(bi) { return (state.pages && state.pages["b" + bi]) || 0; }
function hiddenUnlocked(bi) { return pagesOf(bi) >= PAGES_NEED[bi]; }
const DAN_ZONE = ["凡尘", "炼气", "筑基", "结丹", "元婴", "化神", "炼虚", "合体", "大乘", "渡劫", "真仙", "天仙"];
function craftAreaHTML() {
  const bi = bigIdx();
  const groups = {};
  for (const id of Object.keys(RECIPES)) {
    const big = RECIPES[id].big;
    (groups[big] = groups[big] || []).push(id);
  }
  let html = `<div class="al-sec">开炉炼丹 <i>已通晓「${DAN_ZONE[Math.min(bi, 11)] || "?"}」及以下丹道</i></div>`;
  for (let big = 0; big <= bi; big++) {
    const list = groups[big];
    if (!list || !list.length) continue;
    html += `<div class="al-zone">${DAN_ZONE[big] || big} · 丹道</div>`;
    for (const id of list) {
      const rp = RECIPES[id];
      if (!rp) continue;
      if (rp.h) {
        if (hiddenUnlocked(big)) html += recipeCardHTML(id);
        else {
          const got = pagesOf(big);
          html += `<div class="al-secret"><div class="bd">
            <div class="qn">???.${DAN_ZONE[big]}古方残卷 <span class="pg">残页 ${got}/${PAGES_NEED[big]}</span></div>
            <div class="tip">云游${DAN_ZONE[big]}一带有机会拾得残页，凑齐自见丹方真容。</div></div></div>`;
        }
        continue;
      }
      html += recipeCardHTML(id);
    }
  }
  if (bi < 11) html += `<div class="al-empty" style="font-style:italic">更高一境的丹方，待你亲临其境，自有丹师相授。</div>`;
  return html;
}
function recipeCardHTML(id) {
  const rp = RECIPES[id];
  const needTxt = Object.keys(rp.need).map(mid => {
    const have = (state.mats || {})[mid] || 0, nd = rp.need[mid];
    return `<span class="al-chip ${have >= nd ? "ok" : "no"}">${MATS[mid].n} ${have}/${nd}</span>`;
  }).join("");
  const can = Object.keys(rp.need).every(mid => ((state.mats || {})[mid] || 0) >= rp.need[mid]);
  return `<div class="al-card${can ? " can" : ""}">
    <div style="flex:1;min-width:0">
      <div class="nm">${rp.n}</div>
      <div class="ds">${rp.d}</div>
      <div class="nd">${needTxt}</div>
    </div>
    <button class="al-craft ${can ? "on" : "off"}" ${can ? `onclick="craftPill('${id}')"` : "disabled"}>开炉</button>
  </div>`;
}
function craftPill(id) {
  const rp = RECIPES[id]; if (!rp) return;
  if (rp.h && !hiddenUnlocked(rp.big)) { pushMsg("main", "丹方残页未集齐，此丹方还锁在雾里"); return; }
  for (const mid in rp.need) {
    if (((state.mats || {})[mid] || 0) < rp.need[mid]) {
      pushMsg("main", "材料不齐，丹炉难以为继"); return;
    }
  }
  for (const mid in rp.need) state.mats[mid] -= rp.need[mid];
  state.pills[id] = (state.pills[id] || 0) + 1;
  pushMsg("main", `丹炉开火，一炉<span class="r">${rp.n}</span>成了，药香满室。`);
  pushMsg("avatar", `阿青闻到药香，在丹炉边蹲成一团，尾巴尖轻轻晃`);
  /* v1.9.8 工程化工作台: 成丹即清炉, 重开工作台 */
  selRecipe = null; cauldron = {};
  save(); cloudSoon(); updateHUD(); refreshOpenPanel();
}


/* ==================== v0.7.0 后端权威结算(Cloud Settle) ==================== */
/* 云端档案净化: 动态叙事(云游/离线见闻等随机正文)不上云,
 * 只保留可还原的 剧情 sid 引用 与 纪事; 本地存档保持完整不受影响 */
function cloudSnap(src) {
  const s = src || state;
  const out = Object.assign({}, s);
  out.journal = trimJr((s.journal || []).filter(j => !(j && !j.sid && j.kind === "游历")));
  /* v1.7.26: 未定道号(_named=0)不上传名字与本地临时名 → 服务器/风云榜只见定名者 */
  if (!out._named) { delete out.name; delete out._pn; }
  /* v1.8.0: 上传「账本值」而不是「预测值」—— 本地预测只是显示, 若把预测一起传上去,
     服务端会在预测值之上再发一次同一段时间的收益, 造成双倍。把预测量扣掉即可。 */
  if (_pred.exp) out.exp = Math.max(0, (out.exp || 0) - _pred.exp);
  if (_pred.spirit) out.spirit = Math.max(0, (out.spirit || 0) - _pred.spirit);
  return out;
}
/* ==================== v0.8.1 在线寄包: 化身在外, 周期寄回手札 ==================== */
let _stayLast = 0;
/* v1.9.0: 本轮 settle 是否发生了「化身归来」。v1.9.0 起归来只由服务端在"玩家上线"时判定
 * (在外满 8 封 = 4 小时), 服务端会在 gains.travel 里给出归来事件; 前端据此清本地 travel。 */
let _travelReturned = false;
function adoptKeep(st) {          // 采用结算后的存档, 但本地叙事(非云端净化)不回退
  const keep = (state.journal || []).slice();
  const hadTravel = state.travel;          // 采纳前的本地云游状态
  const c = adopt(st);
  if (!c) return false;
  c.journal = keep.length >= (c.journal || []).length ? keep : c.journal;
  /* v1.8.1 派发竞态保护(沿用): 心跳的普通 settle 不该把刚派发的云游抹掉。
   * 只有当服务端明确给出「化身归来」事件(gains.travel)时才认可清空。
   * v1.9.0 补充: 归来由「满 8 封」决定, 因此若本地已发满 8 封而服务端尚未判归来,
   * 也保留 travel —— 等下一次上线结算时由服务端统一收走, 不在此提前清。 */
  if (hadTravel && !c.travel && !_travelReturned) {
    c.travel = hadTravel;
  }
  state = c;
  try { localStorage.setItem(SAVE_KEY, JSON.stringify(state)); } catch (e) {}
  travelBtnLbl();            // 云端结算可能清 travel(化身归来) → 按钮文字同步
  renderPillHints();         // v1.9.8c.2: 结算合并后药力过期段已被服务端清掉 → 药力行同步
  mailDot();
  return true;
}
function mailLine(locId, ts) {
  const loc = locById(locId);
  if (!loc || !loc.tale || !loc.tale.length) return "";
  const t = loc.tale.length;
  return loc.tale[(((ts || 0) / 60000 | 0) % t + t) % t];
}
function mailDot() {
  const n = (state.mails || []).length;
  const d = $("mailDot"); if (d) d.style.display = n ? "block" : "none";
  const b = $("mailChip"); if (b) b.classList.toggle("has-mail", !!n);
}
function showTravelMail(mail) {
  const loc = locById(mail.loc);
  const where = loc ? loc.n : "远方";
  pushMsg("avatar", `鸿雁衔书而至｜化身自${where}寄回一封手札`);
  pushMsg("main", `<span class="b">雁书已入信匣</span>：化身在${where}写了封信，内附几样远行收获。<br>点右上角鸿雁展开，收取后方才归你。`);
  if ($("mailModal") && $("mailModal").classList.contains("show")) renderMailBox();
  mailDot();
}
async function stayMailCheck() {
  if (!window.fetch || !cld.id || !cld.ready) return;
  if (!state.travel || !state.travel.loc) return;          // 化身不在外无需寄信
  /* v1.9.0: 寄信周期 30 分钟, 故心跳每 2 分钟问一次足矣(周期远大于轮询间隔)。
   * 服务端 stayTravel 是幂等的 —— 多问几次不会多发信, 只保证"到点即寄"。 */
  const now0 = Date.now();
  if (now0 - _stayLast < 120000) return;
  _stayLast = now0;
  const ctl = new AbortController();
  const tm = setTimeout(() => ctl.abort(), 7000);
  try {
    const r = await fetch(CLD_API + "?id=" + encodeURIComponent(cld.id) + "&stay=1", {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ __z: await g1Pack(cloudSnap(state)) }),
      signal: ctl.signal,
    });
    clearTimeout(tm);
    if (!r.ok) return;
    const j = await r.json();
    if (j && j.ok && j.data) {
      const c0 = await g1Unpack(j.data);
      if (c0 && adoptKeep(c0)) { updateHUD(); mailDot(); }
      if (j.stay && j.stay.id && ((j.stay.mats && j.stay.mats.length) || j.stay.page)) {
        showTravelMail(j.stay);
        updateRealmUI();
      }
    }
  } catch (e) { clearTimeout(tm); }
}
/* ==================== v0.8.0 丹方残页(Cloud Settle) 辅助 ==================== */
async function cloudSettle() {
  if (!window.fetch || !cld.id) return null;
  cldUI("sync");
  const t0 = Date.now();
  /* v1.8.0: 客户端不再报"离线基准"、也不再指定区间终点 —— 区间完全由服务端自己的两次写入间隔决定。
     这里只需要上传账本快照(见 cloudSnap: 已扣掉本地预测)。 */
  let snap = null;
  try { snap = cloudSnap(JSON.parse(JSON.stringify(state))); } catch (e) { return null; }
  const ctl = new AbortController();
  const tm = setTimeout(() => ctl.abort(), 8000);
  try {
    const r = await fetch(CLD_API + "?id=" + encodeURIComponent(cld.id) + "&device=" + encodeURIComponent(deviceId()) + "&settle=1", {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ __z: await g1Pack(snap) }),
      signal: ctl.signal,
    });
    clearTimeout(tm);
    if (!r.ok) throw new Error("http" + r.status);
    const j = await r.json();
    /* v2.3 单点登录: 服务端判定其他设备在线 → 踢掉本端, 停止一切操作 */
    if (j && j.kicked) { handleKicked(); return null; }
    if (j && j.ok && j.data) {
      const t1 = Date.now();
      /* 时钟校准(NTP 式): 用往返中点估计服务端"此刻"的时间, 抵消一半网络延迟。
         之后 srvNow() 就是可信的服务端时间, 所有时间显示/判断都用它, 不再用 Date.now()。 */
      if (typeof j.serverTime === "number") _srvOffset = j.serverTime - (t0 + (t1 - t0) / 2);
      if (j.rate) _rate = { exp: +j.rate.exp || 0, spirit: +j.rate.spirit || 0 };
      /* v1.8.1: 先判定本轮是否「真归来」, 再 adopt —— adoptKeep 据此决定是否保留本地 travel */
      _travelReturned = !!(j.gains && j.gains.travel);
      const j0 = await g1Unpack(j.data);
      if (!adoptKeep(j0)) return null;
      _travelReturned = false;
      _pred.exp = 0; _pred.spirit = 0;     // 账本已被服务端权威值覆盖 → 本地预测清零, 从新账本重新开始
      state._lastTs0 = Date.now(); state._settledTs = Date.now();
      mailDot();
      state._cloudTs = j.ts || Date.now();
      cld.ready = true; cld.lastOkTs = Date.now(); cld.lastOkLocal = state.lastTs;
      cld.lastPushTs = Date.now();
      cldUI("on");
      return j;               // { settled, gains, mode, serverTime, rate, data }
    }
    return null;
  } catch (e) {
    clearTimeout(tm);
    cldFail(e);
    return null;
  }
}
/* v2.3 单点登录: 被其他设备顶下线 → 全屏提示, 停止游戏循环和心跳, 禁止操作 */
let _kicked = false;
function handleKicked() {
  if (_kicked) return;
  _kicked = true;
  try {
    const ov = document.createElement("div");
    ov.id = "kickedOverlay";
    ov.style.cssText = "position:fixed;inset:0;z-index:9999;background:rgba(8,10,16,.96);display:flex;flex-direction:column;align-items:center;justify-content:center;color:#e8ecf5;text-align:center;padding:40px;";
    ov.innerHTML = '<div style="font-size:48px;margin-bottom:16px">⚠️</div>'
      + '<div style="font-size:20px;font-weight:bold;margin-bottom:12px;color:#ffb36b">账号已在其他设备登录</div>'
      + '<div style="font-size:14px;color:#a7b0c4;line-height:1.8;max-width:320px">同一玩家码只允许一端在线。<br>如需在本设备继续游玩，请刷新页面重新登录。</div>'
      + '<button onclick="location.reload()" style="margin-top:24px;padding:12px 36px;font-size:16px;background:#67c9ab;color:#0a0e14;border:none;border-radius:8px;cursor:pointer;font-weight:bold">重新登录</button>';
    document.body.appendChild(ov);
  } catch (e) {}
  /* 停止心跳和主循环: 不再上传, 防止旧端覆盖新端存档 */
  cld.ready = false;
  try { SND.suspend(); } catch (e) {}
}
function presentSettle(r) {
  const gg = (r && r.gains) || {};
  if (!gg || !gg.settled) return;
  const dt = gg.dt || 0;
  const hh = Math.floor(dt / 3600), mm = Math.floor((dt % 3600) / 60);
  /* v1.9.5: 面板结构化 —— 收益行(修为/灵石/巡猎) + 「机缘已收」朱印(CSS), 告别内联 style 拼串。
   * 云游产出仍全在【鸿雁信匣】(v1.9.0 约定), 此处只字提示。 */
  const icoExp = '<svg viewBox="0 0 20 20" aria-hidden="true"><path d="M10 2.2 C13.8 2.6 16.6 5 17.4 8.4 C18.2 12.4 15.4 16.2 11.4 17.2 C10.9 17.3 10.4 17.3 10 17.2 C6 16.8 2.8 13.6 2.6 9.8 C2.4 6.2 5.2 3 9 2.3 C9.3 2.3 9.7 2.2 10 2.2 Z" fill="none" stroke="#d8b06a" stroke-width="1.5"/><circle cx="10" cy="10" r="3.1" fill="none" stroke="#d8b06a" stroke-width="1.3" opacity=".75"/><path d="M10 5.4 C11.8 5.9 13.2 7.2 13.6 9" fill="none" stroke="#d8b06a" stroke-width="1" stroke-linecap="round" opacity=".55"/></svg>';
  const icoSpi = '<svg viewBox="0 0 20 20" aria-hidden="true"><path d="M10 1.5 L18.5 10 L10 18.5 L1.5 10 Z" fill="#67c9ab"/><path d="M10 1.5 L10 18.5 L18.5 10 Z" fill="#b7ecda"/><path d="M10 1.5 L1.5 10 L10 10 Z" fill="#9de0c9"/></svg>';
  const icoHunt = '<svg viewBox="0 0 20 20" aria-hidden="true"><path d="M3.4 16.8 C6.8 12.4 11.2 8 16.2 3.6 C17 4.2 17.4 4.8 17.6 5.6 C13.4 10.6 8.8 14.8 4.4 17.6 C4 17.4 3.7 17.1 3.4 16.8 Z" fill="#c9a86a"/><path d="M2.6 13.8 C4.8 11.6 6.6 12.4 6.6 14.6" fill="none" stroke="#c9a86a" stroke-width="1.4" stroke-linecap="round"/></svg>';
  /* 巡猎行 + 细节小字(胜率/秘境/阿青收宝/熔炼) —— 原 huntTxtOf 的结构化替身 */
  const H = gg.hunt;
  let huntRows = "", huntExtra = "";
  if (H && H.waves) {
    const kN = H.keptCount != null ? H.keptCount : (Array.isArray(H.kept) ? H.kept.length : (H.kept || 0));
    huntRows =
      `<div class="off-row"><span class="o-ico">${icoHunt}</span><span class="ol">巡猎 ${H.waves} 波 · 修为</span><b class="ov">+${fmt(H.exp || 0)}</b></div>` +
      `<div class="off-row"><span class="o-ico">${icoSpi}</span><span class="ol">巡猎斩获 · 灵石</span><b class="ov jade">+${fmt(H.spirit || 0)}</b></div>`;
    const bits = [`斗法 ${H.fights} 场（胜 ${H.wins} · 负 ${H.loses}）`, `秘境 ${H.mysts} 处`];
    if (kN) bits.push(`阿青收下 <b>${kN}</b> 件新宝${H.keptName ? `（${H.keptName} 等）` : ""}`);
    if (H.melted) bits.push(`<b>${H.melted}</b> 件投炉熔作灵石 +${fmt(H.meltSp || 0)}`);
    huntExtra = `<div class="off-hunt">${bits.join("；")}。</div>`;
  }
  /* v1.9.8: 连破境 → 横幅右上朱印; 闭关时长 → 横幅标题带(各一行小字) */
  const sealEl = $("offSeal");
  if (sealEl) {
    if (gg.jumps && gg.jumps > 0) { sealEl.style.display = ""; sealEl.textContent = `连破 ${gg.jumps} 境`; }
    else sealEl.style.display = "none";
  }
  const offTEl = $("offTitle");
  if (offTEl) offTEl.innerHTML =
    `闭关 ${hh ? hh + " 时" + (mm ? " " : "") : ""}${mm ? mm + " 分" : (hh ? "" : "片刻")}<i>化身替你行走的账，都回来了</i>`;
  /* v1.9.0: 信匣满则化身停笔, 只提一句(细节在云游面板) */
  const bagTip = (state.travel && state.travel.loc && (state.mails || []).length >= MAIL_CAP)
    ? `<div class="off-hunt" style="color:#a98a5a">鸿雁信匣已满 ${MAIL_CAP} 封，化身暂时停笔 —— 拆几封它便续上。</div>` : "";
  $("offlineText").innerHTML =
    `<div class="off-rows">` +
    `<div class="off-row"><span class="o-ico">${icoExp}</span><span class="ol">周天运转 · 修为</span><b class="ov">+${fmt(gg.exp)}</b></div>` +
    `<div class="off-row"><span class="o-ico">${icoSpi}</span><span class="ol">聚灵阵 · 灵石</span><b class="ov jade">+${fmt(gg.spirit)}</b></div>` +
    huntRows +
    `</div>` + huntExtra + bagTip;
  // 离线际遇叙事(每满 1 时辰一段, 至多 3 段; 纯叙事)
  const bi = Math.min(bigIdx(), MAIN_STORY.length - 1);
  const bigName = realm().big;
  const cnt = Math.min(3, Math.max(1, Math.floor(dt / 3600)));
  const lines = [];
  for (let i = 0; i < cnt; i++) {
    const line = pickNoRepeat(MAIN_STORY[bi], "off" + bi);
    lines.push(line);
    addJournal({ key: "off-" + Date.now() + "-" + i, big: bigName, kind: "游历", title: "洞天游历", text: line });
  }
  const taleEl = $("offlineTale");
  if (taleEl && lines.length) {
    taleEl.style.display = "block";
    taleEl.innerHTML = `<b>离线际遇</b>${lines.map(x => `<br>· ${x}`).join("")}`;
  }
  $("offlineModal").classList.add("show");
  updateRealmUI(); updateHUD();
}


/* ============ v0.8.1 鸿雁信匣: 收信 → 展信 → 点收取入账 ============ */
const MAIL_BTN_PATH = "M12 8 C28 2 44 10 62 6 C78 3 94 9 112 6 C128 3 146 8 162 5 C178 2 192 8 197 15 C200 24 197 33 194 40 C192 46 196 52 182 53 C168 55 152 49 138 53 C122 57 108 50 92 54 C76 58 60 52 46 55 C32 58 20 52 10 54 C2 54 2 46 3 38 C4 28 2 20 6 14 C8 11 10 9 12 8 Z";
function openMail() {
  const m = $("mailModal"); if (!m) return;
  renderMailBox();
  m.classList.add("show");
}
