/* ==================== v1.7.60 设置面板 ====================
 * 原来只有一个"声音开关"按钮, 现在收进设置: 音乐 / 音效 独立开关 + 黑屏挂机。 */
function openSettings() {
  const m = $("setModal"); if (!m) return;
  renderSettings();
  m.classList.add("show");
}
function closeSettings() { const m = $("setModal"); if (m) m.classList.remove("show"); }
function renderSettings() {
  for (const [id, on] of [["setBgm", SND.bgmOn], ["setSfx", SND.sfxOn]]) {
    const r = $(id); if (!r) continue;
    r.classList.toggle("off", !on);
    const st = r.querySelector(".set-st"); if (st) st.textContent = on ? "开" : "关";
  }
}
function toggleBgm() { SND.setBgm(!SND.bgmOn); renderSettings(); }
function toggleSfx() { SND.setSfx(!SND.sfxOn); renderSettings(); }

/* ==================== v1.7.61 黑屏挂机 ====================
 * 进入即静音(音乐+音效), 只留一块低亮度战绩: 打了多少场、掉了什么。
 * 退出必须滑动解锁条 —— 防误触, 单点屏幕不会进游戏。 */
const DIMSTAT = { on: false, battles: 0, win: 0, spirit: 0, exp: 0, loot: [] };

function dimRender() {
  const b = $("dimBattles"); if (b) b.textContent = DIMSTAT.battles;
  const s = $("dimSpirit"); if (s) s.textContent = fmt(DIMSTAT.spirit);
  const e = $("dimExp"); if (e) e.textContent = fmt(DIMSTAT.exp);
  const l = $("dimLoot"); if (!l) return;
  if (!DIMSTAT.loot.length) {
    l.innerHTML = '<div class="li empty">尚未拾获物什</div>';
    return;
  }
  l.innerHTML = DIMSTAT.loot.slice(-8).map(x =>
    `<div class="li q${x.q || 0}">拾获 <b>「${x.n}」</b> ${x.qn}·${x.slot}</div>`).join("");
}
/* 战斗结算时调用(btlWin / btlLose) */
function dimNoteWin(g, ge, drop) {
  if (!DIMSTAT.on) return;
  DIMSTAT.battles++; DIMSTAT.win++;
  DIMSTAT.spirit += g; DIMSTAT.exp += ge;
  if (drop) DIMSTAT.loot.push(drop);
  dimRender();
}
function dimNoteLose() {
  if (!DIMSTAT.on) return;
  DIMSTAT.battles++;
  dimRender();
}

function resetDimKnob() {
  const k = $("dimKnob");
  if (k) { k.style.transition = "left .22s ease"; k.style.left = "4px"; }
}

function enterDim() {
  closeSettings();
  const d = $("dimScreen"); if (!d) return;
  d.classList.add("show");
  document.body.classList.add("dimmed");
  DIMSTAT.on = true;
  DIMSTAT.battles = 0; DIMSTAT.win = 0; DIMSTAT.spirit = 0; DIMSTAT.exp = 0; DIMSTAT.loot = [];
  dimRender();
  SND.mute(true);                                  // 音乐 + 音效 全关(硬静音, 音效不会自己跳出来)
  try { if (window.__bgCtrl && window.__bgCtrl.pause) window.__bgCtrl.pause(); } catch (e) {}
  resetDimKnob();
}

function exitDim() {
  const d = $("dimScreen"); if (!d) return;
  d.classList.remove("show");
  document.body.classList.remove("dimmed");
  DIMSTAT.on = false;
  SND.mute(false);                                 // 按玩家原有开关恢复
  try { if (window.__bgCtrl && window.__bgCtrl.resume) window.__bgCtrl.resume(); } catch (e) {}
}

/* 滑动解锁: 拖到 88% 处松手才进游戏 */
(function initDimSlide() {
  const track = $("dimSlide"), knob = $("dimKnob");
  if (!track || !knob) return;
  let dragging = false, max = 0;
  const xOf = e => (e.touches && e.touches[0] ? e.touches[0].clientX : e.clientX);
  const down = e => {
    dragging = true;
    max = Math.max(1, track.clientWidth - knob.offsetWidth - 8);
    knob.style.transition = "none";
    if (e.cancelable) e.preventDefault();
  };
  const move = e => {
    if (!dragging) return;
    const r = track.getBoundingClientRect();
    let x = xOf(e) - r.left - knob.offsetWidth / 2;
    x = Math.max(4, Math.min(max + 4, x));
    knob.style.left = x + "px";
    if (x - 4 >= max * 0.88) { dragging = false; resetDimKnob(); exitDim(); }
    if (e.cancelable) e.preventDefault();
  };
  const up = () => { if (!dragging) return; dragging = false; resetDimKnob(); };
  knob.addEventListener("pointerdown", down);
  document.addEventListener("pointermove", move, { passive: false });
  document.addEventListener("pointerup", up);
  document.addEventListener("pointercancel", up);
  knob.addEventListener("touchstart", down, { passive: false });
  document.addEventListener("touchmove", move, { passive: false });
  document.addEventListener("touchend", up);
})();
function renderMailBox() {
  const box = $("mailBody"); if (!box) return;
  const ml = (state.mails || []).slice().sort((a, b) => (b.ts || 0) - (a.ts || 0));
  /* v1.8.2 一键收取: 信匣有条数时显示批量条 */
  const bar = $("mailBulkBar"), cnt = $("mailBulkCount");
  if (bar) bar.style.display = ml.length ? "" : "none";
  if (cnt) cnt.textContent = ml.length ? `共 ${ml.length} 封` : "";
  if (!ml.length) {
    box.innerHTML = `<div class="mail-empty">信匣空空。<br>遣化身出门远行，它每半小时便会托雁足捎信回来——<br>到时候，记得拆开看看。</div>`;
    return;
  }
  box.innerHTML = ml.map(m => {
    const loc = locById(m.loc);
    const where = loc ? loc.n : "远方";
    const mins = Math.max(1, Math.round((Date.now() - (m.ts || Date.now())) / 60000));
    const ag = mins >= 60 ? (mins / 60 >= 24 ? Math.round(mins / 1440) + " 天前" : Math.round(mins / 60) + " 小时前") : mins + " 分钟前";
    /* v1.9.9e 内附物品图标化: 缩小的 ico 物品图 + 名称 + 数量(图标库 assets/modals/ico/<id>.webp);
       丹方残页无专属图, 用内联纸卷 SVG 兜底; 无附件显示平安信 */
    const chips = [];
    for (const mk of (m.mats || [])) if (MATS[mk.id]) {
      chips.push(`<span class="mg" title="${MATS[mk.id].n}"><img src="assets/modals/ico/${mk.id}.webp" alt="" onerror="this.remove()"><em>${MATS[mk.id].n}</em><i>×${mk.q}</i></span>`);
    }
    if (m.page) chips.push(`<span class="mg" title="丹方残页"><svg viewBox="0 0 24 24"><path d="M7 3.5h7.2L18.5 8v12.5H7z" fill="#e8dcc0" stroke="rgba(140,110,60,.55)" stroke-width="1.1"/><path d="M14.2 3.5 18.5 8h-4.3z" fill="#c9b98f"/><path d="M9.2 11.5h6.4M9.2 14.2h6.4M9.2 16.9h4.2" stroke="rgba(120,95,55,.5)" stroke-width="1.1" stroke-linecap="round"/></svg><em>丹方残页</em><i>×1</i></span>`);
    const goods = chips.length
      ? `<span class="m-gl">内附</span>${chips.join("")}`
      : `<span class="m-plain">一封平安信，无甚物什</span>`;
    return `<div class="mail-item">
      <div class="mail-head">
        <span class="m-loc" title="${where}">${where.slice(0, 1)}</span>
        <span class="m-from">${where} · 化身亲笔</span>
        <span class="m-age">${ag}</span>
      </div>
      <p class="mail-txt">“${mailLine(m.loc, m.ts)}”</p>
      <div class="mail-foot">
        <span class="m-goods">${goods}</span>
        <button class="btn primary seal" type="button" onclick="collectMail('${m.id}')"><span class="label">收 取</span></button>
      </div>
    </div>`;
  }).join("");
}
/* v1.8.2 一键收取: 把信匣内全部信件一次入账。
 * 设计: 复用单封的入账逻辑, 汇总成一条消息(不敢信匣轰炸聊天窗), 末尾一次性落盘。 */
/* v1.8.4 收取信件的服务端确认: 把"这封信已被收"同步给服务端。
 * 不这么做的话, 下一次 settle 会拿服务端旧档的信匣去合并, 玩家收了信还会被"退回" → 重复收取。
 * claim 成功则由服务端落档(信已删); 失败(断网)只标脏, 下次心跳再补。 */
async function mailClaim(idOrAll) {
  if (!window.fetch || !cld.id || !cld.ready) { cloudSoon(); return; }
  try {
    const r = await fetch(CLD_API + "?id=" + encodeURIComponent(cld.id) + "&claim=" + encodeURIComponent(idOrAll), {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ __z: await g1Pack(cloudSnap(state)) }),
    });
    const j = r.ok ? await r.json() : null;
    if (j && j.ok && j.data) {
      const c0 = await g1Unpack(j.data);
      if (c0 && adoptKeep(c0)) { mailDot(); updateHUD(); }
    } else { cloudSoon(); }
  } catch (e) { cloudSoon(); }
}
function collectAllMail() {
  const ml = state.mails || [];
  if (!ml.length) return;
  const total = {};
  let pages = 0, n = 0;
  for (const m of ml) {
    for (const mk of (m.mats || [])) {
      if (!MATS[mk.id]) continue;
      state.mats[mk.id] = (state.mats[mk.id] || 0) + mk.q;
      total[mk.id] = (total[mk.id] || 0) + mk.q;
    }
    if (m.page) {
      const z = zoneOfLoc(m.loc);
      if (z) { state.pages["b" + z.big] = (state.pages["b" + z.big] || 0) + 1; pages++; }
    }
    n++;
  }
  state.mails = [];
  const gotTxt = Object.keys(total).map(id => MATS[id].n + "×" + total[id]).join("、");
  pushMsg("main", `你一并拆开 <b>${n}</b> 封雁书，收下 <span class="r">${gotTxt || "数纸见闻"}</span>`
    + (pages ? `，另得 <b>丹方残页×${pages}</b>` : "") + "。");
  pushMsg("avatar", `展信收取 · 共 ${n} 封`);
  renderMailBox(); mailDot(); updateHUD();
  save(); mailClaim("all");            // v1.8.4: 告知服务端清空信匣, 防重复收取
}
function collectMail(id) {
  const ml = state.mails || [];
  const i = ml.findIndex(x => String(x.id) === String(id));
  if (i < 0) return;
  const m = ml[i];
  const got = [];
  for (const mk of (m.mats || [])) {
    if (!MATS[mk.id]) continue;
    state.mats[mk.id] = (state.mats[mk.id] || 0) + mk.q;
    got.push(MATS[mk.id].n + "×" + mk.q);
  }
  if (m.page) {
    const z = zoneOfLoc(m.loc);
    if (z) { state.pages["b" + z.big] = (state.pages["b" + z.big] || 0) + 1; got.push("丹方残页×1"); }
  }
  ml.splice(i, 1);
  const loc = locById(m.loc);
  const where = loc ? loc.n : "远方";
  const gotTxt = got.length ? '收下 <span class="r">' + got.join("、") + "</span>" : "只余一纸见闻";
  pushMsg("main", "你拆开" + where + "的来信，" + gotTxt + "。");
  pushMsg("avatar", "展信收取 · 化身自" + where + "寄回");
  renderMailBox(); mailDot(); updateHUD();
  save(); mailClaim(m.id);             // v1.8.4: 告知服务端删掉这封, 防重复收取
}


